sp_widget.client_script:
api.controller = function() {
  var c = this;
  c.data.categories = ["All", "Laptop", "Textbook", "Lab Kit"];
  c.data.activeCategory = "All";
  c.data.filters = { department: "", availability: "", location: "" };

  c.setCategory = function(cat) {
    c.data.activeCategory = cat;
    c.filterAssets();
  };

  c.filterAssets = function() {
    // Broadcasts the current query/filters so the Asset Grid widget can react.
    // Simplest approach: use $rootScope.$broadcast, or move search+grid
    // into ONE widget once you're ready to wire this up for real.
  };
};

sp_widget.css:
.catalog-search {
  width: 86%;
  max-width: 1200px;
  margin: 30px auto 20px;
}

.search-bar {
  display: flex;
  height: 48px;
  background: #fff;
  border: 1px solid #d4d4d4;
  border-radius: 4px;
  margin-bottom: 15px;
}

.search-bar input {
  flex: 1;
  border: none;
  outline: none;
  padding: 0 15px;
  font-size: 15px;
}

.search-bar button {
  width: 55px;
  border: none;
  border-left: 1px solid #eee;
  background: #fff;
  cursor: pointer;
}

.category-pills {
  display: flex;
  gap: 10px;
  margin-bottom: 15px;
}

.pill {
  padding: 8px 18px;
  font-size: 13px;
  border-radius: 20px;
  border: 1px solid #d4d4d4;
  background: #fff;
  cursor: pointer;
}

.pill.active {
  background: #e60028;
  color: white;
  border-color: #e60028;
}

.filters {
  display: flex;
  gap: 12px;
}

.filters select {
  padding: 8px 12px;
  font-size: 13px;
  border: 1px solid #d4d4d4;
  border-radius: 4px;
  background: #fff;
}

@media (max-width: 768px) {
  .category-pills, .filters {
    flex-wrap: wrap;
  }
}
